  vec3 ret = vec3(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  vec4 o = 0;
// CONV: Center on screen, then try some uAspect correction
uv = (uv * 2.0) - 1.0;
uv *= uAspect.xy;
// CONV: Adjust this to flip the output (±uv.x, ±uv.y)
uv = vec2(uv.x, -uv.y);
vec2 u = uv;
float i=0,a,d,s,t=uTime*.3;
vec3 p = vec3(uv.yx, 1.0 );
