u.x += .3;
#ifdef bass_smooth
float fac = (int)vis_version > 2 ? 2.0 * vis_intensity+vis_shift : ((int)vis_version == 1 ? 3-2*smoothstep( 0.0 , 2.0 ,bass_smooth) : 3.0 - smoothstep( 0.0 , 2.0 ,audioLowSmooth)) * vis_intensity + vis_shift;
